#include <bits/stdc++.h>
using namespace std;

int main() {
    // Print the 8-bit pattern of several values
    for (int v : {127, 1, 0, -1, -127, -128}) {
        int8_t x = static_cast<int8_t>(v);
        cout << setw(5) << v << " = " << bitset<8>(static_cast<unsigned char>(x)) << "\n";
    }
    // Negate by flipping all bits and adding one
    int8_t a = 5;
    int8_t neg = static_cast<int8_t>(~a + 1);
    cout << "negate 5 -> " << static_cast<int>(neg) << "\n";
    // abs(INT_MIN) overflows int; compute it safely in unsigned
    int m = INT_MIN;
    unsigned int mag = 0u - static_cast<unsigned int>(m);
    cout << "INT_MIN = " << m << ", safe magnitude = " << mag << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

// Check BEFORE adding: the addition itself would be undefined behavior
bool addOverflows(int a, int b) {
    return b > 0 ? a > INT_MAX - b : a < INT_MIN - b;
}

int main() {
    unsigned int u = UINT_MAX;
    u = u + 1;  // defined: wraps modulo 2^32
    cout << "UINT_MAX + 1 = " << u << "\n";

    int a = INT_MAX, b = 1;
    cout << "INT_MAX + 1 would overflow? " << addOverflows(a, b) << "\n";
    cout << "10 + 20 would overflow? " << addOverflows(10, 20) << "\n";

    int r;
    // GCC/Clang builtin: returns true when the result did not fit
    bool bad = __builtin_add_overflow(a, b, &r);
    cout << "builtin says overflow: " << bad << "\n";

    long long wide = static_cast<long long>(a) + b;  // compute in a wider type
    cout << "in long long: " << wide << "\n";
    return 0;
}

