int main() {
    vector<int> v;  // empty
    // size() is unsigned, so size() - 1 wraps to a huge number
    cout << "v.size() - 1 = " << v.size() - 1 << "\n";
    cout << "buggy loop condition 0 < size()-1: " << (0 < v.size() - 1) << "\n";
    cout << "safe: " << (0 < static_cast<long long>(v.size()) - 1) << "\n";

    cout << "-1 < 1u        : " << (-1 < 1u) << "\n";           // -1 becomes huge unsigned
    cout << "cmp_less(-1,1u): " << std::cmp_less(-1, 1u) << "\n"; // compares real values

    uint16_t a = 65535;
    // a * a is computed as int (overflow!), so widen first
    uint32_t p = static_cast<uint32_t>(a) * a;
    cout << "65535*65535 widened = " << p << "\n";

    cout << "type of 'a'+1 is int: " << is_same_v<decltype('a' + 1), int> << "\n";
    cout << "'a' + 1 = " << 'a' + 1 << "\n";
    return 0;
}

