#include <iostream>
#include <iterator>
#include <vector>
#include <string>

namespace app {
    // our own function named like std::distance
    int distance(int a, int b) { return b > a ? b - a : a - b; }
}

int main() {
    std::vector<int> v = {1, 2, 3, 4};
    // Qualified names make it obvious which function is called
    std::cout << "app::distance(3, 10) = " << app::distance(3, 10) << "\n";
    std::cout << "std::distance over v = "
              << std::distance(v.begin(), v.end()) << "\n";

    using std::cout;  // targeted using-declaration: one name only
    cout << "using-declaration works\n";

    {
        using namespace std::literals;  // small scope: acceptable
        auto s = "hello"s;              // std::string literal
        cout << s << " has " << s.size() << " chars\n";
    }
    return 0;
}

#include <iostream>
#include <utility>

namespace shapes {
    struct Box { int w; };
    // Found through ADL because Box lives in namespace shapes
    void swap(Box& a, Box& b) {
        std::cout << "  shapes::swap called\n";
        std::swap(a.w, b.w);
    }
}

template <class T>
void mySwap(T& a, T& b) {
    using std::swap;  // fallback for types without their own swap
    swap(a, b);       // unqualified call: ADL may find a better one
}

int main() {
    int x = 1, y = 2;
    std::cout << "swap ints (std::swap):\n";
    mySwap(x, y);
    std::cout << "  x=" << x << " y=" << y << "\n";

    shapes::Box a{10}, b{20};
    std::cout << "swap boxes (custom):\n";
    mySwap(a, b);
    std::cout << "  a.w=" << a.w << " b.w=" << b.w << "\n";
    return 0;
}

#include <iostream>

struct Logger {
    const char* name;
    Logger(const char* n) : name(n) { std::cout << "construct " << name << "\n"; }
    ~Logger() { std::cout << "destroy   " << name << "\n"; }
};

Logger g1("global1");  // runs before main, in declaration order within a TU
Logger g2("global2");
constinit int limit = 42;  // C++20: guaranteed constant initialization

// Construct on first use: initialized when first called, thread-safe since C++11
Logger& lazy() {
    static Logger l("lazy");
    return l;
}

int main() {
    std::cout << "main starts, limit = " << limit << "\n";
    lazy();
    lazy();  // second call does not construct again
    std::cout << "main ends\n";
    return 0;  // statics are destroyed in reverse order of construction
}

#include <iostream>
#include <mutex>

// C++17 inline variable: put this in a header; all TUs share ONE object
inline int maxConn = 100;

// constexpr constant: each TU gets its own copy, fine for values that never change
constexpr int kTimeoutMs = 2500;

// Encapsulated, lazily created, with a mutex for run-time changes
struct Config {
    int retries = 3;
    std::mutex m;
};
Config& config() {
    static Config c;  // no initialization-order problem
    return c;
}

int main() {
    std::cout << "maxConn = " << maxConn << "\n";
    maxConn = 250;  // visible to every file that includes the header
    std::cout << "maxConn after change = " << maxConn << "\n";
    std::cout << "kTimeoutMs = " << kTimeoutMs << "\n";
    {
        std::lock_guard<std::mutex> g(config().m);
        config().retries = 5;
    }
    std::cout << "retries = " << config().retries << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

// Each helper refuses the input that would be undefined behavior
bool safeDiv(int a, int b, int& out) {
    if (b == 0 || (a == INT_MIN && b == -1)) return false;  // INT_MIN / -1 overflows
    out = a / b;
    return true;
}
bool safeShift(int v, int s, int& out) {
    if (s < 0 || s >= 32) return false;  // shift count must be in [0, 31]
    out = static_cast<int>(static_cast<unsigned>(v) << s);
    return true;
}
constexpr int square(int x) { return x * x; }

int main() {
    int r;
    cout << "INT_MIN / -1 ok? " << safeDiv(INT_MIN, -1, r) << "\n";
    cout << "100 / 7 ok? " << safeDiv(100, 7, r) << " -> " << r << "\n";
    cout << "1 << 32 ok? " << safeShift(1, 32, r) << "\n";
    cout << "1 << 5 ok? " << safeShift(1, 5, r) << " -> " << r << "\n";
    // Overflow inside constexpr is a compile error, so UB cannot hide there
    constexpr int sq = square(46340);
    cout << "46340^2 = " << sq << "\n";
    unsigned char c = 200;
    cout << "isalpha(unsigned char 200) = " << (isalpha(c) != 0) << "\n";
    return 0;
}
